#include <immintrin.h>

// dot product, 4 doubles per instruction (compile with -mavx2 -mfma)
double dot(const double* x, const double* y, std::size_t n) {
    __m256d acc = _mm256_setzero_pd();            // 4 lanes of 0.0
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        __m256d a = _mm256_loadu_pd(x + i);       // load 4 doubles (unaligned ok)
        __m256d b = _mm256_loadu_pd(y + i);
        acc = _mm256_fmadd_pd(a, b, acc);         // acc += a*b, per lane
    }
    double t[4];
    _mm256_storeu_pd(t, acc);
    double s = t[0] + t[1] + t[2] + t[3];         // horizontal sum of lanes
    for (; i < n; ++i) s += x[i] * y[i];          // scalar tail for n % 4
    return s;
}
